def close(got, exp: List[float], rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if np.isnan(exp[i]):
            if not np.isnan(g[i]):
                print("mismatch at", i, g[i], exp[i])
                return False
            continue
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

