def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

X, y = data(40, 5, 3)
Y = np.column_stack((X[:, 0] - X[:, 1] + 0.1 * np.sin(np.arange(40.0)), X[:, 2] * 0.5 + X[:, 3], np.cos(np.arange(40.0))))
Q = X[:6] + 0.1
R = 1e-8
A = 1e-10

m = PLSRegression(n_components=3).fit(X, Y)
check(close(m.x_weights_, plsr_xw, R, A), "plsr x_weights"); check(close(m.y_loadings_, plsr_yl, R, A), "plsr y_loadings")
check(close(m.coef_, plsr_coef, R, A), "plsr coef"); check(close(m.predict(Q), plsr_pred, R, A), "plsr pred")
check(close(m.transform(Q), plsr_tr, R, A), "plsr transform"); check(close(m.x_scores_[:5], plsr_xs, R, A), "plsr x_scores")
check(close(m.n_iter_, plsr_it), "plsr n_iter")
m1 = PLSRegression(n_components=2, scale=False).fit(X, np.ascontiguousarray(Y[:, 0]))
check(close(m1.predict(Q), plsr1_pred, R, A), "plsr 1d pred"); check(close(m1.coef_, plsr1_coef, R, A), "plsr 1d coef")
m2 = PLSCanonical(n_components=2).fit(X, Y)
check(close(m2.x_weights_, plsc_xw, R, A), "plsc xw"); check(close(m2.y_weights_, plsc_yw, R, A), "plsc yw")
check(close(m2.predict(Q), plsc_pred, R, A), "plsc pred"); check(close(m2.inverse_transform(m2.transform(Q)), plsc_inv, R, A), "plsc inverse")
check(close(PLSCanonical(n_components=2, algorithm="svd").fit(X, Y).x_rotations_, plscs_xr, R, A), "plsc svd")
m3 = CCA(n_components=2).fit(X, Y)
check(close(m3.x_weights_, cca_xw, 1e-6, 1e-8), "cca xw"); check(close(m3.y_rotations_, cca_yr, 1e-6, 1e-8), "cca yr")
check(close(m3.predict(Q), cca_pred, 1e-6, 1e-8), "cca pred")
m4 = PLSSVD(n_components=2).fit(X, Y)
check(close(m4.x_weights_, plssvd_xw, R, A), "plssvd xw"); check(close(m4.y_weights_, plssvd_yw, R, A), "plssvd yw")
check(close(m4.transform(Q), plssvd_tr, R, A), "plssvd transform")

yu = y.copy()
for i in range(0, 40, 3):
    yu[i] = -1
for i in range(1, 40, 5):
    yu[i] = -1
lp = LabelPropagation(gamma=0.5).fit(X, yu)
check(close(lp.label_distributions_[:8], lp_ld, R, A), "lp ld"); check(close(lp.transduction_, lp_tr), "lp transduction")
check(close(lp.predict_proba(Q), lp_proba, R, A), "lp proba"); check(lp.n_iter_ == lp_it, "lp n_iter")
ls = LabelSpreading(gamma=0.5, alpha=0.3).fit(X, yu)
check(close(ls.label_distributions_[:8], ls_ld, R, A), "ls ld"); check(close(ls.transduction_, ls_tr), "ls transduction")
check(close(ls.predict_proba(Q), ls_proba, R, A), "ls proba"); check(ls.n_iter_ == ls_it, "ls n_iter")
lk = LabelSpreading(kernel="knn", n_neighbors=5).fit(X, yu)
check(close(lk.transduction_, lsk_tr), "ls knn transduction"); check(close(lk.predict_proba(Q), lsk_proba, R, A), "ls knn proba")
check(close(LabelPropagation(kernel="knn", n_neighbors=4).fit(X, yu).transduction_, lpk_tr), "lp knn transduction")
st = SelfTrainingClassifier(GaussianNB(), threshold=0.9).fit(X, yu)
check(close(st.transduction_, st_tr), "st transduction"); check(close(st.labeled_iter_, st_li), "st labeled_iter")
check(st.n_iter_ == st_it and st.termination_condition_ == st_term, "st n_iter/term"); check(close(st.predict(Q), st_pred), "st pred")
st2 = SelfTrainingClassifier(GaussianNB(), criterion="k_best", k_best=3, max_iter=2).fit(X, yu)
# GaussianNB probabilities saturate at 1.0 (ulp-level ties): compare the
# number of samples labeled per iteration rather than which ones
cnt = [0, 0, 0, 0]
cexp = [0, 0, 0, 0]
for i in range(40):
    cnt[int(st2.labeled_iter_[i]) + 1] += 1
    cexp[int(stk_li[i]) + 1] += 1
check(cnt == cexp, "st kbest labeled_iter counts"); check(st2.termination_condition_ == stk_term, "st kbest term")

if failed:
    print("TEST FAILED", failed)
    sys.exit(1)
print("OK")
